class Solution:
    def mostPoints(self, questions: List[List[int]]) -> int:
        n = len(questions)
        dp = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            pts, bp = questions[i]
            next_idx = min(n, i + bp + 1)
            dp[i] = max(dp[i + 1], pts + dp[next_idx])
        return dp[0]

class Solution {
public:
    long long mostPoints(vector<vector<int>>& questions) {
        int n = questions.size();
        vector<long long> dp(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            long long pts = questions[i][0];
            int bp = questions[i][1];
            int nextIdx = min(n, i + bp + 1);
            dp[i] = max(dp[i + 1], pts + dp[nextIdx]);
        }
        return dp[0];
    }
};

class Solution {
